def ppv(pi: float, Se: float, Sp: float) -> float:
    return (Se*pi) / (Se*pi + (1-Sp)*(1-pi))

def npv(pi: float, Se: float, Sp: float) -> float:
    return (Sp*(1-pi)) / (Sp*(1-pi) + (1-Se)*pi)

priors = [0.01, 0.1, 0.5]
Se, Sp = 0.95, 0.95
for p0 in priors:
    print(f"Prior={p0:.2f}  PPV={ppv(p0,Se,Sp):.3f}  NPV={npv(p0,Se,Sp):.3f}")
